reference_solution:
def convert(s, num_rows):
    if num_rows == 1 or num_rows >= len(s):
        return s
    rows = [[] for _ in range(num_rows)]
    row, direction = 0, 1
    for char in s:
        rows[row].append(char)
        if row == 0:
            direction = 1
        elif row == num_rows - 1:
            direction = -1
        row += direction
    return "".join("".join(values) for values in rows)

